(8192, 'plPL', 'Pieszczota animisty', '', '', '', 'Wróć do Zanzy Niespokojnego.', '', '', '', '', 0),
(9208, 'plPL', 'Dziki strażnik – Arkanum ochrony', 'Zanza potrafi stworzyć wiele pradawnych trollowych zaklęć, jeśli ma odpowiednie składniki! Czy $gsłyszałeś:słyszałaś; o Dzikim strażniku? Nie, oczywiście, że nie. Twój umysł jest otumaniony pośledniejszą elfią magią.$B$BPrzynieś mi arkanum elfiego wyrobu, żebym mógł zniszczyć to wynaturzenie. Zrób to, a Dziki strażnik będzie twój.$B', 'Zanza Niespokojny w Zul\'Gurub chce dostać Arkanum ochrony.', '', 'Wróć do Zanzy Niespokojnego w Zul\'Gurub.', '', '', '', '', 0),
(9209, 'plPL', 'Dziki strażnik – Arkanum szybkości', 'Zanza potrafi stworzyć wiele pradawnych trollowych zaklęć, jeśli ma odpowiednie składniki! Czy $gsłyszałeś:słyszałaś; o Dzikim strażniku? Nie, oczywiście, że nie. Twój umysł jest otumaniony pośledniejszą elfią magią.$B$BPrzynieś mi arkanum elfiego wyrobu, żebym mógł zniszczyć to wynaturzenie. Zrób to, a Dziki strażnik będzie twój.$B', 'Zanza Niespokojny w Zul\'Gurub chce dostać Arkanum szybkości.', '', 'Wróć do Zanzy Niespokojnego w Zul\'Gurub.', '', '', '', '', 0),
(9210, 'plPL', 'Dziki strażnik – Arkanum skupienia', 'Zanza potrafi stworzyć wiele pradawnych trollowych zaklęć, jeśli ma odpowiednie składniki! Czy $gsłyszałeś:słyszałaś; o Dzikim strażniku? Nie, oczywiście, że nie. Twój umysł jest otumaniony pośledniejszą elfią magią.$B$BPrzynieś mi arkanum elfiego wyrobu, żebym mógł zniszczyć to wynaturzenie. Zrób to, a Dziki strażnik będzie twój.$B', 'Zanza Niespokojny w Zul\'Gurub chce dostać Arkanum skupienia.', '', 'Wróć do Zanzy Niespokojnego w Zul\'Gurub.', '', '', '', '', 0);
