INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(8251, 'plPL', '%s umiera.', '', 0),
(10026, 'plPL', 'Niech rozwiną się sploty nienawiści!', '', 0),
(10027, 'plPL', '', 'Panie Hir\'eeku, użycz mi skrzydeł zemsty!', 0),
(10369, 'plPL', '', 'Rozkazuję wam spuścić deszcz ognia na tych najeźdźców!', 0),
(10370, 'plPL', '', '%s wydaje ogłuszający wrzask!', 0),
(10425, 'plPL', '%s staje cały w płomieniach, a w jego oczach pojawia się obłęd!', '', 0),
(10436, 'plPL', 'Twoja czaszka ozdobić nasze ołtarze rytualne!', 'Twoja czaszka ozdobić nasze ołtarze rytualne!', 0),
(10437, 'plPL', 'Trollowe mojo to najsilniejsze mojo!', 'Trollowe mojo to najsilniejsze mojo!', 0),
(10438, 'plPL', 'Poczujcie wielkie złe wudu!', 'Poczujcie wielkie złe wudu!', 0),
(10443, 'plPL', '', 'Shadro, uczyń mnie swoim awatarem!', 0),
(10444, 'plPL', '', 'Pomiot nie upadnie!', 0),
(10447, 'plPL', 'PYCHA ZWIASTUJE KONIEC WASZEGO ŚWIATA. CHODŹCIE, ŚMIERTELNICY! STAWCIE CZOŁA GNIEWOWI DUSZOŻERCY!', '', 0),
(10448, 'plPL', '', 'Pomóż mi, mój pomiocie!', 0),
(10449, 'plPL', 'Witajcie na wielkim przedstawieniu, przyjaciele. Podchodźcie śmiało i umierajcie!', '', 0),
(10451, 'plPL', 'Hakkar już mnie nie zniewala! Nareszcie spokój!', '', 0),
(10452, 'plPL', '', 'Nareszcie... śmierć! Przeklinam cię, Hakkarze! Przeklinam!', 0),
(10453, 'plPL', '%s umiera.', '%s umiera.', 0),
(10455, 'plPL', 'Shirvallah, napełnij mnie swoim GNIEWEM!', '', 0),
(10459, 'plPL', '', 'Bądźcie błogosławieni, śmiertelnicy, za to wyzwolenie... Hakkar już nade mną nie panuje!', 0),
(10460, 'plPL', 'Ssspokój... nareszccie!', '', 0),
(10463, 'plPL', 'Jestem Zanza, loa z Zandalaru. Przybyłem z Zandalaru w tej eterycznej postaci, by pomóc mojemu ludowi. Hakkar nie ma władzy nad moją duszą.$B$BPomagam tym, którzy pomogli ludowi Zandalaru.', '', 0),
(10464, 'plPL', '$GPrzyjaciel:Przyjaciółka; Zandalarów! $GZapuściłeś:Zapuściłaś; się głęboko w leże Boga Krwi, $N. Dobrze zrobisz, jeśli wysłuchasz tego, co mam do powiedzenia.$B$BWiele tysięcy lat temu, gdy rdzenne trolle z imperium Zul\'Aman walczyły z najeźdźcami, pogańskimi wysokimi elfami, skradziono Zanzie wielką magię. Wysokie elfy użyły tej magii, by zaczarować swoją broń i zbroje i łatwiej podbić trolle w tym regionie.', '', 0),
(10465, 'plPL', 'Chyba $gsłyszałem:słyszałam; o tej magii.', 'Chyba $gsłyszałem:słyszałam; o tej magii.', 0),
(10466, 'plPL', 'Doprawdy? Zatem wiesz, jak słaba i żałosna była wersja trollowej magii wysokich elfów?$B$BWysokie elfy nie mogły pojąć, czemu lud o takim jak one darze do magii nie może się mierzyć z potęgą trollowego wudu. Dla bladoskórych było to nie do pojęcia. Musiały się zadowolić wypaczoną wersją trollowych zaklęć. Zdaje się, że nazywały je „arkanum”.\n', '', 0),
(10467, 'plPL', 'Arkanum? Coś mi to mówi.', 'Arkanum? Coś mi to mówi.', 0),
(10468, 'plPL', 'Zanza potrafi stworzyć pradawne trollowe zaklęcia, jeśli ma odpowiednie składniki. Ta magia pomoże ci pokonać Hakkara i jego sługi.$B$BProszę tylko, byś $gprzyniósł:przyniosła; mi dwie rzeczy.', '', 0),
(10469, 'plPL', 'Jakie to składniki?', 'Jakie to składniki?', 0),
(10470, 'plPL', 'Pierwsza to pierwotny symbol, który trzeba odebrać najpotężniejszym z poruczników Hakkari: Jin\'do i Władcy Krwi.$B$BDruga to przekłuta lalka wudu. Można je znaleźć w stosach odpadków, którymi zaśmiecone jest to plugawe miejsce. Zajrzyj do przeklętych stosów hoodoo.$B$BPrzynieś mi te rzeczy, a stworzę dla ciebie potężne zaklęcie!', '', 0),
(10484, 'plPL', 'Znaki na tej tablicy przedstawiają pradawne diagramy i kryją groźne słowa mocy, lecz ich znaczenie pozostaje dla ciebie nieodgadnione.', '', 0),
(10485, 'plPL', 'Znaki na tej tablicy przedstawiają pradawne diagramy i groźne słowa mocy, służące do stworzenia Szaleństwa mojo Gurubashi...', '', 0),
(10486, 'plPL', 'Naucz się receptury.', 'Naucz się receptury.', 0),
(10487, 'plPL', 'Znaki na tej tablicy przedstawiają pradawne diagramy i kryją groźne słowa mocy.$B$BSądzisz, że to receptura alchemiczna, ale przekracza twoje umiejętności...', '', 0),
(10494, 'plPL', '', '%s zaczyna rzucać Wielkie uzdrowienie!', 0),
(10496, 'plPL', 'Gri\'lek z Żelaznej Krwi$B$BWędrowiec. Niech jego siła i żądza walki przetrwają wieki.$B$BGri\'lek przebywa teraz daleko stąd. Pewnego dnia może powrócić...', '', 0),
(10505, 'plPL', 'DING!', '', 0),
(10507, 'plPL', 'Wasza śmierć karmi moją siłę!', '', 0),
(10538, 'plPL', 'Gri\'lek z Żelaznej Krwi$B$BWędrowiec. Niech jego siła i żądza walki przetrwają wieki.$B$BGri\'lek trwa teraz na krawędzi szaleństwa...', '', 0),
(10539, 'plPL', 'Hazza\'rah, Tkacz Snów.$B$BJego moc to moc koszmarów; oby jego wrogowie nigdy się nie przebudzili.$B$BHazza\'rah przebywa teraz daleko stąd. Pewnego dnia może powrócić...', '', 0),
(10540, 'plPL', 'Hazza\'rah, Tkacz Snów.$B$BJego moc to moc koszmarów; oby jego wrogowie nigdy się nie przebudzili.$B$BHazza\'rah śni teraz na krawędzi szaleństwa.', '', 0),
(10541, 'plPL', 'Renataki z Tysiąca Ostrzy.$B$BBól to jego życiodajna krew. Strach – jego sojusznik. Oby pewnego dnia powrócił i przyniósł ze sobą radosny rozlew krwi.$B$BRenataki przebywa teraz daleko stąd. Pewnego dnia może powrócić...', '', 0),
(10542, 'plPL', 'Renataki z Tysiąca Ostrzy.$B$BBól to jego życiodajna krew. Strach – jego sojusznik. Oby pewnego dnia powrócił i przyniósł ze sobą radosny rozlew krwi.$B$BRenataki przebywa teraz na krawędzi szaleństwa.', '', 0),
(10543, 'plPL', 'Wushoolay, Wiedźma Burzy.$B$BJego moc to moc nieba, deszczu i roztrzaskanej ziemi. Oby znów panował jako ojciec Gurubaszów.$B$BWushoolay przebywa teraz daleko stąd. Pewnego dnia może powrócić...', '', 0),
(10544, 'plPL', 'Wushoolay, Wiedźma Burzy.$B$BJego moc to moc nieba, deszczu i roztrzaskanej ziemi. Oby znów panował jako ojciec Gurubaszów.$B$BWushoolay szaleje teraz na krawędzi obłędu.', '', 0),
(10545, 'plPL', '%s wpada w szał na widok swojego raptora poległego w bitwie!', '%s wpada w szał na widok swojego raptora poległego w bitwie!', 0),
(10546, 'plPL', 'Słudzy Hakkara, słuchajcie swojego boga. Świętość tej świątyni została naruszona. Najeźdźcy wkraczają na świętą ziemię! Ołtarza Krwi trzeba bronić. Zabijcie ich wszystkich!', '', 0),
(10550, 'plPL', 'Wasza bezduszna pogarda dla suwerennej potęgi Imperium Gurubaszów nie umknęła uwadze. Mieszkańcy Zul\'Gurub zostali powiadomieni o waszej obecności.', '', 0),
(10590, 'plPL', 'Pod moimi rządami świat zazna niezmierzonych okrucieństw.', '', 0),
(10593, 'plPL', 'Przysięgnijcie wierność Hakkarowi, a wasze cierpienie będzie znikome.', '', 0),
(10594, 'plPL', 'Śmiecie stawiać stopę na świętej ziemi Hakkari? Słudzy Hakkara, zniszczcie niewiernych!\n', '', 0),
(10635, 'plPL', 'Ucieczka nic wam nie da, śmiertelnicy!', '', 0);
